16 `include "common_cells/registers.svh"
17 
18 module fpnew_cast_multi #(
19   parameter fpnew_pkg::fmt_logic_t   FpFmtConfig  = '1,
20   parameter fpnew_pkg::ifmt_logic_t  IntFmtConfig = '1,
21   // FPU configuration
22   parameter int unsigned             NumPipeRegs = 0,
23   parameter fpnew_pkg::pipe_config_t PipeConfig  = fpnew_pkg::BEFORE,
24   parameter type                     TagType     = logic,
25   parameter type                     AuxType     = logic,
26   // Do not change
27   localparam int unsigned WIDTH = fpnew_pkg::maximum(fpnew_pkg::max_fp_width(FpFmtConfig),
28                                                      fpnew_pkg::max_int_width(IntFmtConfig)),
29   localparam int unsigned NUM_FORMATS = fpnew_pkg::NUM_FP_FORMATS,
30   localparam int unsigned ExtRegEnaWidth = NumPipeRegs == 0 ? 1 : NumPipeRegs
31 ) (
32   input  logic                   clk_i,
33   input  logic                   rst_ni,
34   // Input signals
35   input  logic [WIDTH-1:0]       operands_i, // 1 operand
36   input  logic [NUM_FORMATS-1:0] is_boxed_i, // 1 operand
37   input  fpnew_pkg::roundmode_e  rnd_mode_i,
38   input  fpnew_pkg::operation_e  op_i,
39   input  logic                   op_mod_i,
40   input  fpnew_pkg::fp_format_e  src_fmt_i,
41   input  fpnew_pkg::fp_format_e  dst_fmt_i,
42   input  fpnew_pkg::int_format_e int_fmt_i,
43   input  TagType                 tag_i,
44   input  logic                   mask_i,
45   input  AuxType                 aux_i,
46   // Input Handshake
47   input  logic                   in_valid_i,
48   output logic                   in_ready_o,
49   input  logic                   flush_i,
50   // Output signals
51   output logic [WIDTH-1:0]       result_o,
52   output fpnew_pkg::status_t     status_o,
53   output logic                   extension_bit_o,
54   output TagType                 tag_o,
55   output logic                   mask_o,
56   output AuxType                 aux_o,
57   // Output handshake
58   output logic                   out_valid_o,
59   input  logic                   out_ready_i,
60   // Indication of valid data in flight
61   output logic                   busy_o,
62   // External register enable override
63   input  logic [ExtRegEnaWidth-1:0] reg_ena_i
64 );
65 
66   // ----------
67   // Constants
68   // ----------
69   localparam int unsigned NUM_INT_FORMATS = fpnew_pkg::NUM_INT_FORMATS;
70   localparam int unsigned MAX_INT_WIDTH   = fpnew_pkg::max_int_width(IntFmtConfig);
71 
72   localparam fpnew_pkg::fp_encoding_t SUPER_FORMAT = fpnew_pkg::super_format(FpFmtConfig);
73 
74   localparam int unsigned SUPER_EXP_BITS = SUPER_FORMAT.exp_bits;
75   localparam int unsigned SUPER_MAN_BITS = SUPER_FORMAT.man_bits;
76   localparam int unsigned SUPER_BIAS     = 2**(SUPER_EXP_BITS - 1) - 1;
77 
78   // The internal mantissa includes normal bit or an entire integer
79   localparam int unsigned INT_MAN_WIDTH = fpnew_pkg::maximum(SUPER_MAN_BITS + 1, MAX_INT_WIDTH);
80   // If needed, there will be a LZC for renormalization
81   localparam int unsigned LZC_RESULT_WIDTH = $clog2(INT_MAN_WIDTH);
82   // The internal exponent must be able to represent the smallest denormal input value as signed
83   // or the number of bits in an integer
84   localparam int unsigned INT_EXP_WIDTH = fpnew_pkg::maximum($clog2(MAX_INT_WIDTH),
85       fpnew_pkg::maximum(SUPER_EXP_BITS, $clog2(SUPER_BIAS + SUPER_MAN_BITS))) + 1;
86   // Pipelines
87   localparam NUM_INP_REGS = PipeConfig == fpnew_pkg::BEFORE
88                             ? NumPipeRegs
89                             : (PipeConfig == fpnew_pkg::DISTRIBUTED
90                                ? ((NumPipeRegs + 1) / 3) // Second to get distributed regs
91                                : 0); // no regs here otherwise
92   localparam NUM_MID_REGS = PipeConfig == fpnew_pkg::INSIDE
93                           ? NumPipeRegs
94                           : (PipeConfig == fpnew_pkg::DISTRIBUTED
95                              ? ((NumPipeRegs + 2) / 3) // First to get distributed regs
96                              : 0); // no regs here otherwise
97   localparam NUM_OUT_REGS = PipeConfig == fpnew_pkg::AFTER
98                             ? NumPipeRegs
99                             : (PipeConfig == fpnew_pkg::DISTRIBUTED
100                                ? (NumPipeRegs / 3) // Last to get distributed regs
101                                : 0); // no regs here otherwise
102 
103   // ---------------
104   // Input pipeline
105   // ---------------
106   // Selected pipeline output signals as non-arrays
107   logic [WIDTH-1:0]       operands_q;
108   logic [NUM_FORMATS-1:0] is_boxed_q;
109   logic                   op_mod_q;
110   fpnew_pkg::fp_format_e  src_fmt_q;
111   fpnew_pkg::fp_format_e  dst_fmt_q;
112   fpnew_pkg::int_format_e int_fmt_q;
113 
114   // Input pipeline signals, index i holds signal after i register stages
115   logic                   [0:NUM_INP_REGS][WIDTH-1:0]       inp_pipe_operands_q;
116   logic                   [0:NUM_INP_REGS][NUM_FORMATS-1:0] inp_pipe_is_boxed_q;
117   fpnew_pkg::roundmode_e  [0:NUM_INP_REGS]                  inp_pipe_rnd_mode_q;
118   fpnew_pkg::operation_e  [0:NUM_INP_REGS]                  inp_pipe_op_q;
119   logic                   [0:NUM_INP_REGS]                  inp_pipe_op_mod_q;
120   fpnew_pkg::fp_format_e  [0:NUM_INP_REGS]                  inp_pipe_src_fmt_q;
121   fpnew_pkg::fp_format_e  [0:NUM_INP_REGS]                  inp_pipe_dst_fmt_q;
122   fpnew_pkg::int_format_e [0:NUM_INP_REGS]                  inp_pipe_int_fmt_q;
123   TagType                 [0:NUM_INP_REGS]                  inp_pipe_tag_q;
124   logic                   [0:NUM_INP_REGS]                  inp_pipe_mask_q;
125   AuxType                 [0:NUM_INP_REGS]                  inp_pipe_aux_q;
126   logic                   [0:NUM_INP_REGS]                  inp_pipe_valid_q;
127   // Ready signal is combinatorial for all stages
128   logic [0:NUM_INP_REGS] inp_pipe_ready;
129 
130   // Input stage: First element of pipeline is taken from inputs
131   assign inp_pipe_operands_q[0] = operands_i;
132   assign inp_pipe_is_boxed_q[0] = is_boxed_i;
133   assign inp_pipe_rnd_mode_q[0] = rnd_mode_i;
134   assign inp_pipe_op_q[0]       = op_i;
135   assign inp_pipe_op_mod_q[0]   = op_mod_i;
136   assign inp_pipe_src_fmt_q[0]  = src_fmt_i;
137   assign inp_pipe_dst_fmt_q[0]  = dst_fmt_i;
138   assign inp_pipe_int_fmt_q[0]  = int_fmt_i;
139   assign inp_pipe_tag_q[0]      = tag_i;
140   assign inp_pipe_mask_q[0]     = mask_i;
141   assign inp_pipe_aux_q[0]      = aux_i;
142   assign inp_pipe_valid_q[0]    = in_valid_i;
143   // Input stage: Propagate pipeline ready signal to updtream circuitry
144   assign in_ready_o = inp_pipe_ready[0];
145   // Generate the register stages
146   for (genvar i = 0; i < NUM_INP_REGS; i++) begin : gen_input_pipeline
147     // Internal register enable for this stage
148     logic reg_ena;
149     // Determine the ready signal of the current stage - advance the pipeline:
150     // 1. if the next stage is ready for our data
151     // 2. if the next stage only holds a bubble (not valid) -> we can pop it
152     assign inp_pipe_ready[i] = inp_pipe_ready[i+1] | ~inp_pipe_valid_q[i+1];
153     // Valid: enabled by ready signal, synchronous clear with the flush signal
154     `FFLARNC(inp_pipe_valid_q[i+1], inp_pipe_valid_q[i], inp_pipe_ready[i], flush_i, 1'b0, clk_i, rst_ni)
155     // Enable register if pipleine ready and a valid data item is present
156     assign reg_ena = (inp_pipe_ready[i] & inp_pipe_valid_q[i]) | reg_ena_i[i];
157     // Generate the pipeline registers within the stages, use enable-registers
158     `FFL(inp_pipe_operands_q[i+1], inp_pipe_operands_q[i], reg_ena, '0)
159     `FFL(inp_pipe_is_boxed_q[i+1], inp_pipe_is_boxed_q[i], reg_ena, '0)
160     `FFL(inp_pipe_rnd_mode_q[i+1], inp_pipe_rnd_mode_q[i], reg_ena, fpnew_pkg::RNE)
161     `FFL(inp_pipe_op_q[i+1],       inp_pipe_op_q[i],       reg_ena, fpnew_pkg::FMADD)
162     `FFL(inp_pipe_op_mod_q[i+1],   inp_pipe_op_mod_q[i],   reg_ena, '0)
163     `FFL(inp_pipe_src_fmt_q[i+1],  inp_pipe_src_fmt_q[i],  reg_ena, fpnew_pkg::fp_format_e'(0))
164     `FFL(inp_pipe_dst_fmt_q[i+1],  inp_pipe_dst_fmt_q[i],  reg_ena, fpnew_pkg::fp_format_e'(0))
165     `FFL(inp_pipe_int_fmt_q[i+1],  inp_pipe_int_fmt_q[i],  reg_ena, fpnew_pkg::int_format_e'(0))
166     `FFL(inp_pipe_tag_q[i+1],      inp_pipe_tag_q[i],      reg_ena, TagType'('0))
167     `FFL(inp_pipe_mask_q[i+1],     inp_pipe_mask_q[i],     reg_ena, '0)
168     `FFL(inp_pipe_aux_q[i+1],      inp_pipe_aux_q[i],      reg_ena, AuxType'('0))
169   end
170   // Output stage: assign selected pipe outputs to signals for later use
171   assign operands_q = inp_pipe_operands_q[NUM_INP_REGS];
172   assign is_boxed_q = inp_pipe_is_boxed_q[NUM_INP_REGS];
173   assign op_mod_q   = inp_pipe_op_mod_q[NUM_INP_REGS];
174   assign src_fmt_q  = inp_pipe_src_fmt_q[NUM_INP_REGS];
175   assign dst_fmt_q  = inp_pipe_dst_fmt_q[NUM_INP_REGS];
176   assign int_fmt_q  = inp_pipe_int_fmt_q[NUM_INP_REGS];
177 
178   // -----------------
179   // Input processing
180   // -----------------
181   logic src_is_int, dst_is_int; // if 0, it's a float
182 
183   assign src_is_int = (inp_pipe_op_q[NUM_INP_REGS] == fpnew_pkg::I2F);
184   assign dst_is_int = (inp_pipe_op_q[NUM_INP_REGS] == fpnew_pkg::F2I);
185 
186   logic [INT_MAN_WIDTH-1:0] encoded_mant; // input mantissa with implicit bit
187 
188   logic        [NUM_FORMATS-1:0]                    fmt_sign;
189   logic signed [NUM_FORMATS-1:0][INT_EXP_WIDTH-1:0] fmt_exponent;
190   logic        [NUM_FORMATS-1:0][INT_MAN_WIDTH-1:0] fmt_mantissa;
191   logic signed [NUM_FORMATS-1:0][INT_EXP_WIDTH-1:0] fmt_shift_compensation; // for LZC
192 
193   fpnew_pkg::fp_info_t [NUM_FORMATS-1:0] info;
194 
195   logic [NUM_INT_FORMATS-1:0][INT_MAN_WIDTH-1:0] ifmt_input_val;
196   logic                                          int_sign;
197   logic [INT_MAN_WIDTH-1:0]                      int_value, int_mantissa;
198 
199   // FP Input initialization
200   for (genvar fmt = 0; fmt < int'(NUM_FORMATS); fmt++) begin : fmt_init_inputs
201     // Set up some constants
202     localparam int unsigned FP_WIDTH = fpnew_pkg::fp_width(fpnew_pkg::fp_format_e'(fmt));
203     localparam int unsigned EXP_BITS = fpnew_pkg::exp_bits(fpnew_pkg::fp_format_e'(fmt));
204     localparam int unsigned MAN_BITS = fpnew_pkg::man_bits(fpnew_pkg::fp_format_e'(fmt));
205 
206     if (FpFmtConfig[fmt]) begin : active_format
207       localparam fpnew_pkg::fp_format_e FpFormat = fpnew_pkg::fp_format_e'(fmt);
208 
209       // Classify input
210       fpnew_classifier #(
211         .FpFormat    ( FpFormat ),
212         .NumOperands ( 1        )
213       ) i_fpnew_classifier (
214         .operands_i ( operands_q[FP_WIDTH-1:0] ),
215         .is_boxed_i ( is_boxed_q[fmt]          ),
216         .info_o     ( info[fmt]                )
217       );
218 
219       assign fmt_sign[fmt]     = operands_q[FP_WIDTH-1];
220       assign fmt_exponent[fmt] = signed'({1'b0, operands_q[MAN_BITS+:EXP_BITS]});
221       assign fmt_mantissa[fmt] = {info[fmt].is_normal, operands_q[MAN_BITS-1:0]}; // zero pad
222       // Compensation for the difference in mantissa widths used for leading-zero count
223       assign fmt_shift_compensation[fmt] = signed'(INT_MAN_WIDTH - 1 - MAN_BITS);
224     end else begin : inactive_format
225       assign info[fmt]                   = '{default: fpnew_pkg::DONT_CARE}; // format disabled
226       assign fmt_sign[fmt]               = fpnew_pkg::DONT_CARE;             // format disabled
227       assign fmt_exponent[fmt]           = '{default: fpnew_pkg::DONT_CARE}; // format disabled
228       assign fmt_mantissa[fmt]           = '{default: fpnew_pkg::DONT_CARE}; // format disabled
229       assign fmt_shift_compensation[fmt] = '{default: fpnew_pkg::DONT_CARE}; // format disabled
230     end
231   end
232 
233   // Sign-extend INT input
234   for (genvar ifmt = 0; ifmt < int'(NUM_INT_FORMATS); ifmt++) begin : gen_sign_extend_int
235     // Set up some constants
236     localparam int unsigned INT_WIDTH = fpnew_pkg::int_width(fpnew_pkg::int_format_e'(ifmt));
237 
238     if (IntFmtConfig[ifmt]) begin : active_format // only active formats
239       always_comb begin : sign_ext_input
240         // sign-extend value only if it's signed
241         ifmt_input_val[ifmt]                = '{default: operands_q[INT_WIDTH-1] & ~op_mod_q};
242         ifmt_input_val[ifmt][INT_WIDTH-1:0] = operands_q[INT_WIDTH-1:0];
243       end
244     end else begin : inactive_format
245       assign ifmt_input_val[ifmt] = '{default: fpnew_pkg::DONT_CARE}; // format disabled
246     end
247   end
248 
249   // Construct input mantissa from integer
250   assign int_value    = ifmt_input_val[int_fmt_q];
251   assign int_sign     = int_value[INT_MAN_WIDTH-1] & ~op_mod_q; // only signed ints are negative
252   assign int_mantissa = int_sign ? unsigned'(-int_value) : int_value; // get magnitude of negative
253 
254   // select mantissa with source format
255   assign encoded_mant = src_is_int ? int_mantissa : fmt_mantissa[src_fmt_q];
256 
257   // --------------
258   // Normalization
259   // --------------
260   logic signed [INT_EXP_WIDTH-1:0] src_bias;      // src format bias
261   logic signed [INT_EXP_WIDTH-1:0] src_exp;       // src format exponent (biased)
262   logic signed [INT_EXP_WIDTH-1:0] src_subnormal; // src is subnormal
263   logic signed [INT_EXP_WIDTH-1:0] src_offset;    // src offset within mantissa
264 
265   assign src_bias      = signed'(fpnew_pkg::bias(src_fmt_q));
266   assign src_exp       = fmt_exponent[src_fmt_q];
267   assign src_subnormal = signed'({1'b0, info[src_fmt_q].is_subnormal});
268   assign src_offset    = fmt_shift_compensation[src_fmt_q];
269 
270   logic                            input_sign;   // input sign
271   logic signed [INT_EXP_WIDTH-1:0] input_exp;    // unbiased true exponent
272   logic        [INT_MAN_WIDTH-1:0] input_mant;   // normalized input mantissa
273   logic                            mant_is_zero; // for integer zeroes
274 
275   logic signed [INT_EXP_WIDTH-1:0] fp_input_exp;
276   logic signed [INT_EXP_WIDTH-1:0] int_input_exp;
277 
278   // Input mantissa needs to be normalized
279   logic [LZC_RESULT_WIDTH-1:0] renorm_shamt;     // renormalization shift amount
280   logic [LZC_RESULT_WIDTH:0]   renorm_shamt_sgn; // signed form for calculations
281 
282   // Leading-zero counter is needed for renormalization
283   lzc #(
284     .WIDTH ( INT_MAN_WIDTH ),
285     .MODE  ( 1             ) // MODE = 1 counts leading zeroes
286   ) i_lzc (
287     .in_i    ( encoded_mant ),
288     .cnt_o   ( renorm_shamt ),
289     .empty_o ( mant_is_zero )
290   );
291   assign renorm_shamt_sgn = signed'({1'b0, renorm_shamt});
292 
293   // Get the sign from the proper source
294   assign input_sign = src_is_int ? int_sign : fmt_sign[src_fmt_q];
295   // Realign input mantissa, append zeroes if destination is wider
296   assign input_mant = encoded_mant << renorm_shamt;
297   // Unbias exponent and compensate for shift
298   assign fp_input_exp  = signed'(src_exp + src_subnormal - src_bias -
299                                  renorm_shamt_sgn + src_offset); // compensate for shift
300   assign int_input_exp = signed'(INT_MAN_WIDTH - 1 - renorm_shamt_sgn);
301 
302   assign input_exp     = src_is_int ? int_input_exp : fp_input_exp;
303 
304   logic signed [INT_EXP_WIDTH-1:0] destination_exp;  // re-biased exponent for destination
305 
306   // Rebias the exponent
307   assign destination_exp = input_exp + signed'(fpnew_pkg::bias(dst_fmt_q));
308 
309   // ---------------
310   // Internal pipeline
311   // ---------------
312   // Pipeline output signals as non-arrays
313   logic                            input_sign_q;
314   logic signed [INT_EXP_WIDTH-1:0] input_exp_q;
315   logic [INT_MAN_WIDTH-1:0]        input_mant_q;
316   logic signed [INT_EXP_WIDTH-1:0] destination_exp_q;
317   logic                            src_is_int_q;
318   logic                            dst_is_int_q;
319   fpnew_pkg::fp_info_t             info_q;
320   logic                            mant_is_zero_q;
321   logic                            op_mod_q2;
322   fpnew_pkg::roundmode_e           rnd_mode_q;
323   fpnew_pkg::fp_format_e           src_fmt_q2;
324   fpnew_pkg::fp_format_e           dst_fmt_q2;
325   fpnew_pkg::int_format_e          int_fmt_q2;
326   // Internal pipeline signals, index i holds signal after i register stages
327 
328 
329   logic                   [0:NUM_MID_REGS]                    mid_pipe_input_sign_q;
330   logic signed            [0:NUM_MID_REGS][INT_EXP_WIDTH-1:0] mid_pipe_input_exp_q;
331   logic                   [0:NUM_MID_REGS][INT_MAN_WIDTH-1:0] mid_pipe_input_mant_q;
332   logic signed            [0:NUM_MID_REGS][INT_EXP_WIDTH-1:0] mid_pipe_dest_exp_q;
333   logic                   [0:NUM_MID_REGS]                    mid_pipe_src_is_int_q;
334   logic                   [0:NUM_MID_REGS]                    mid_pipe_dst_is_int_q;
335   fpnew_pkg::fp_info_t    [0:NUM_MID_REGS]                    mid_pipe_info_q;
336   logic                   [0:NUM_MID_REGS]                    mid_pipe_mant_zero_q;
337   logic                   [0:NUM_MID_REGS]                    mid_pipe_op_mod_q;
338   fpnew_pkg::roundmode_e  [0:NUM_MID_REGS]                    mid_pipe_rnd_mode_q;
339   fpnew_pkg::fp_format_e  [0:NUM_MID_REGS]                    mid_pipe_src_fmt_q;
340   fpnew_pkg::fp_format_e  [0:NUM_MID_REGS]                    mid_pipe_dst_fmt_q;
341   fpnew_pkg::int_format_e [0:NUM_MID_REGS]                    mid_pipe_int_fmt_q;
342   TagType                 [0:NUM_MID_REGS]                    mid_pipe_tag_q;
343   logic                   [0:NUM_MID_REGS]                    mid_pipe_mask_q;
344   AuxType                 [0:NUM_MID_REGS]                    mid_pipe_aux_q;
345   logic                   [0:NUM_MID_REGS]                    mid_pipe_valid_q;
346   // Ready signal is combinatorial for all stages
347   logic [0:NUM_MID_REGS] mid_pipe_ready;
348 
349   // Input stage: First element of pipeline is taken from upstream logic
350   assign mid_pipe_input_sign_q[0] = input_sign;
351   assign mid_pipe_input_exp_q[0]  = input_exp;
352   assign mid_pipe_input_mant_q[0] = input_mant;
353   assign mid_pipe_dest_exp_q[0]   = destination_exp;
354   assign mid_pipe_src_is_int_q[0] = src_is_int;
355   assign mid_pipe_dst_is_int_q[0] = dst_is_int;
356   assign mid_pipe_info_q[0]       = info[src_fmt_q];
357   assign mid_pipe_mant_zero_q[0]  = mant_is_zero;
358   assign mid_pipe_op_mod_q[0]     = op_mod_q;
359   assign mid_pipe_rnd_mode_q[0]   = inp_pipe_rnd_mode_q[NUM_INP_REGS];
360   assign mid_pipe_src_fmt_q[0]    = src_fmt_q;
361   assign mid_pipe_dst_fmt_q[0]    = dst_fmt_q;
362   assign mid_pipe_int_fmt_q[0]    = int_fmt_q;
363   assign mid_pipe_tag_q[0]        = inp_pipe_tag_q[NUM_INP_REGS];
364   assign mid_pipe_mask_q[0]       = inp_pipe_mask_q[NUM_INP_REGS];
365   assign mid_pipe_aux_q[0]        = inp_pipe_aux_q[NUM_INP_REGS];
366   assign mid_pipe_valid_q[0]      = inp_pipe_valid_q[NUM_INP_REGS];
367   // Input stage: Propagate pipeline ready signal to input pipe
368   assign inp_pipe_ready[NUM_INP_REGS] = mid_pipe_ready[0];
369 
370   // Generate the register stages
371   for (genvar i = 0; i < NUM_MID_REGS; i++) begin : gen_inside_pipeline
372     // Internal register enable for this stage
373     logic reg_ena;
374     // Determine the ready signal of the current stage - advance the pipeline:
375     // 1. if the next stage is ready for our data
376     // 2. if the next stage only holds a bubble (not valid) -> we can pop it
377     assign mid_pipe_ready[i] = mid_pipe_ready[i+1] | ~mid_pipe_valid_q[i+1];
378     // Valid: enabled by ready signal, synchronous clear with the flush signal
379     `FFLARNC(mid_pipe_valid_q[i+1], mid_pipe_valid_q[i], mid_pipe_ready[i], flush_i, 1'b0, clk_i, rst_ni)
380     // Enable register if pipleine ready and a valid data item is present
381     assign reg_ena = (mid_pipe_ready[i] & mid_pipe_valid_q[i]) | reg_ena_i[NUM_INP_REGS + i];
382     // Generate the pipeline registers within the stages, use enable-registers
383     `FFL(mid_pipe_input_sign_q[i+1], mid_pipe_input_sign_q[i], reg_ena, '0)
384     `FFL(mid_pipe_input_exp_q[i+1],  mid_pipe_input_exp_q[i],  reg_ena, '0)
385     `FFL(mid_pipe_input_mant_q[i+1], mid_pipe_input_mant_q[i], reg_ena, '0)
386     `FFL(mid_pipe_dest_exp_q[i+1],   mid_pipe_dest_exp_q[i],   reg_ena, '0)
387     `FFL(mid_pipe_src_is_int_q[i+1], mid_pipe_src_is_int_q[i], reg_ena, '0)
388     `FFL(mid_pipe_dst_is_int_q[i+1], mid_pipe_dst_is_int_q[i], reg_ena, '0)
389     `FFL(mid_pipe_info_q[i+1],       mid_pipe_info_q[i],       reg_ena, '0)
390     `FFL(mid_pipe_mant_zero_q[i+1],  mid_pipe_mant_zero_q[i],  reg_ena, '0)
391     `FFL(mid_pipe_op_mod_q[i+1],     mid_pipe_op_mod_q[i],     reg_ena, '0)
