416   // Casting
417   // --------
418   logic [INT_EXP_WIDTH-1:0] final_exp;        // after eventual adjustments
419 
420   logic [2*INT_MAN_WIDTH:0]  preshift_mant;    // mantissa before final shift
421   logic [2*INT_MAN_WIDTH:0]  destination_mant; // mantissa from shifter, with rnd bit
422   logic [SUPER_MAN_BITS-1:0] final_mant;       // mantissa after adjustments
423   logic [MAX_INT_WIDTH-1:0]  final_int;        // integer shifted in position
424 
425   logic [$clog2(INT_MAN_WIDTH+1)-1:0] denorm_shamt; // shift amount for denormalization
426 
427   logic [1:0] fp_round_sticky_bits, int_round_sticky_bits, round_sticky_bits;
428   logic       of_before_round, uf_before_round;
