431   // Perform adjustments to mantissa and exponent
432   always_comb begin : cast_value
433     // Default assignment
434     final_exp       = unsigned'(destination_exp_q); // take exponent as is, only look at lower bits
435     preshift_mant   = '0;  // initialize mantissa container with zeroes
436     denorm_shamt    = SUPER_MAN_BITS - fpnew_pkg::man_bits(dst_fmt_q2); // right of mantissa
437     of_before_round = 1'b0;
438     uf_before_round = 1'b0;
439 
440     // Place mantissa to the left of the shifter
441     preshift_mant = input_mant_q << (INT_MAN_WIDTH + 1);
442 
443     // Handle INT casts
444     if (dst_is_int_q) begin
445       // By default right shift mantissa to be an integer
446       denorm_shamt = unsigned'(MAX_INT_WIDTH - 1 - input_exp_q);
447       // overflow: when converting to unsigned the range is larger by one
448       if ((input_exp_q >= signed'(fpnew_pkg::int_width(int_fmt_q2) - 1 + op_mod_q2))    // Exponent larger than max int range,
449           && !(!op_mod_q2                                                               // unless cast to signed int
450                && input_sign_q                                                          // and input value is larges negative int value
451                && (input_exp_q == signed'(fpnew_pkg::int_width(int_fmt_q2) - 1))
452                && (input_mant_q == {1'b1, {INT_MAN_WIDTH-1{1'b0}}}))) begin
453         denorm_shamt    = '0; // prevent shifting
454         of_before_round = 1'b1;
455       // underflow
456       end else if (input_exp_q < -1) begin
457         denorm_shamt    = MAX_INT_WIDTH + 1; // all bits go to the sticky
458         uf_before_round = 1'b1;
459       end
460     // Handle FP over-/underflows
461     end else begin
462       // Overflow or infinities (for proper rounding)
463       if ((destination_exp_q >= signed'(2**fpnew_pkg::exp_bits(dst_fmt_q2))-1) ||
464           (~src_is_int_q && info_q.is_inf)) begin
465         final_exp       = unsigned'(2**fpnew_pkg::exp_bits(dst_fmt_q2)-2); // largest normal value
466         preshift_mant   = '1;                           // largest normal value and RS bits set
467         of_before_round = 1'b1;
468       // Denormalize underflowing values
469       end else if (destination_exp_q < 1 &&
470                    destination_exp_q >= -signed'(fpnew_pkg::man_bits(dst_fmt_q2))) begin
471         final_exp       = '0; // denormal result
472         denorm_shamt    = unsigned'(denorm_shamt + 1 - destination_exp_q); // adjust right shifting
473         uf_before_round = 1'b1;
474       // Limit the shift to retain sticky bits
475       end else if (destination_exp_q < -signed'(fpnew_pkg::man_bits(dst_fmt_q2))) begin
476         final_exp       = '0; // denormal result
477         denorm_shamt    = unsigned'(denorm_shamt + 2 + fpnew_pkg::man_bits(dst_fmt_q2)); // to sticky
478         uf_before_round = 1'b1;
479       end
480     end
481   end
