489   assign {final_mant, fp_round_sticky_bits[1]} =
490       destination_mant[2*INT_MAN_WIDTH-1-:SUPER_MAN_BITS+1];
491   assign {final_int, int_round_sticky_bits[1]} = destination_mant[2*INT_MAN_WIDTH-:MAX_INT_WIDTH+1];
492   // Collapse sticky bits
493   assign fp_round_sticky_bits[0]  = (| {destination_mant[NUM_FP_STICKY-1:0]});
494   assign int_round_sticky_bits[0] = (| {destination_mant[NUM_INT_STICKY-1:0]});
495 
496   // select RS bits for destination operation
497   assign round_sticky_bits = dst_is_int_q ? int_round_sticky_bits : fp_round_sticky_bits;
