499   // ----------------------------
500   // Rounding and classification
501   // ----------------------------
502   logic [WIDTH-1:0] pre_round_abs;  // absolute value of result before rnd
503   logic             of_after_round; // overflow
504   logic             uf_after_round; // underflow
505 
506   logic [NUM_FORMATS-1:0][WIDTH-1:0] fmt_pre_round_abs; // per format
507   logic [NUM_FORMATS-1:0]            fmt_of_after_round;
508   logic [NUM_FORMATS-1:0]            fmt_uf_after_round;
