510   logic [NUM_INT_FORMATS-1:0][WIDTH-1:0] ifmt_pre_round_abs; // per format
511   logic [NUM_INT_FORMATS-1:0]            ifmt_of_after_round;
512 
513   logic             rounded_sign;
514   logic [WIDTH-1:0] rounded_abs; // absolute value of result after rounding
515   logic             result_true_zero;
516 
517   logic [WIDTH-1:0] rounded_int_res; // after possible inversion
518   logic             rounded_int_res_zero; // after rounding
